/* ================= Practice tax software: a working return simulator laid out like professional web tax software =================
   Tabs follow the real flow: Client Manager ▸ New Return ▸ Personal ▸ Income ▸ Deductions ▸ Payments ▸ Summary ▸ Review ▸ E-File.
   The engine computes a 2026 Form 1040 for wages, interest, a Schedule C business, student loan interest, child credits and payments.
   It does not compute the earned income credit, itemized deductions or state returns; the practice clients avoid those. */
const TSTD={Single:16100,"Married filing jointly":32200,"Head of household":24150,"Married filing separately":16100};
const TBR={Single:[[12400,.10],[50400,.12],[105700,.22],[201775,.24]],"Married filing jointly":[[24800,.10],[100800,.12],[211400,.22],[403550,.24]],"Head of household":[[17700,.10],[67450,.12],[105700,.22],[201750,.24]],"Married filing separately":[[12400,.10],[50400,.12],[105700,.22],[201775,.24]]}; // tax year 2026, Rev. Proc. 2025-32
function ttax(ti,st){if(ti<=0)return 0;const x=ti<100000?Math.floor(ti/50)*50+25:ti,B=TBR[st]||TBR.Single;let t=0,lo=0;   // under $100,000 the IRS Tax Table uses the middle of each $50 row
  for(const [hi,r] of B){if(x>hi){t+=(hi-lo)*r;lo=hi}else{t+=(x-lo)*r;return Math.round(t+1e-9)}}return Math.round(t+(x-lo)*.32)}
function tcalc(r){const n=v=>+v||0,st=r.status||"Single",w=r.w2.reduce((s,x)=>s+n(x.b1),0),wh=r.w2.reduce((s,x)=>s+n(x.b2),0),int=r.int.reduce((s,x)=>s+n(x.b1),0);
  const c=r.c||{},gross=n(c.gross),exp=n(c.adv)+n(c.off)+n(c.rent)+n(c.oth),net=gross-exp,hasC=gross>0||exp>0;
  const seBase=net>=400?Math.round(net*.9235*100)/100:0,se=Math.round(seBase*.153),half=Math.round(seBase*.153/2);
  const sl=Math.min(2500,n(r.sl)),total=w+int+(hasC?net:0),adj=half+sl,agi=total-adj,std=TSTD[st],before=Math.max(0,agi-std);
  const qbi=hasC&&net>0?Math.round(Math.min(.2*(net-half),.2*before)):0,ti=Math.max(0,agi-std-qbi),tax=ttax(ti,st);
  const kids=r.deps.filter(d=>n(d.age)<17&&n(d.mo)>6).length,oth=r.deps.length-kids,ctcMax=kids*2200+oth*500,ctc=Math.min(tax,ctcMax);
  const earned=w+(hasC?Math.max(0,net-half):0),actc=Math.max(0,Math.min(kids*2200-Math.min(ctc,kids*2200),kids*1700,.15*Math.max(0,earned-2500)));
  const totalTax=tax-ctc+se,pay=wh+n(r.est)+Math.round(actc),diff=pay-totalTax;
  return{st,w,int,gross,exp,net,hasC,se,half,sl,total,adj,agi,std,qbi,ti,tax,ctc,actc:Math.round(actc),totalTax,wh,est:n(r.est),pay,refund:Math.max(0,diff),owe:Math.max(0,-diff),kids}}
const W2=(emp,ein,b1,b2)=>({emp,ein,b1,b2,b4:Math.round(b1*6.2)/100,b6:Math.round(b1*1.45)/100});
const w2doc=(x,who)=>Object.assign({k:"w2",who},x);
const t2=v=>(+v).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
function w2Html(x,tap){const e=esc,c=(l,v,w,id,raw)=>tap&&id?`<button type="button" data-ttap="${id}|${e(String(raw))}"><small>${l}</small><b>${e(String(v))}</b></button>`:`<div${w?' class="w"':""}><small>${l}</small><b>${e(String(v))}</b></div>`;
  return `<div class="vis w2${tap?" tap":""}"><div class="w2h"><b>W-2</b> Wage and Tax Statement <b>2026</b><span>${tap?"Tap a green box to send it to the screen below, or type it yourself":"Copy B, to be filed with employee's federal tax return"}</span></div><div class="w2g">
   ${c("a Employee's social security number (practice)",x.ssn||"400-00-0000")}${c("1 Wages, tips, other compensation",t2(x.b1),0,"tw1",x.b1)}${c("2 Federal income tax withheld",t2(x.b2),0,"tw2",x.b2)}
   ${c("b Employer identification number (EIN)",x.ein,0,"twn",x.ein)}${c("3 Social security wages",t2(x.b1))}${c("4 Social security tax withheld",t2(x.b4),0,"tw4",x.b4)}
   ${c("c Employer's name and address",x.emp+", Denver, CO",0,"twe",x.emp)}${c("5 Medicare wages and tips",t2(x.b1))}${c("6 Medicare tax withheld",t2(x.b6),0,"tw6",x.b6)}
   ${c("e Employee's name",x.who.split(" and ")[0],1)}${c("12a See instructions for box 12","")}${c("13 Retirement plan","☐")}
   ${c("15 State · Employer's state ID","CO · 0"+x.ein.replace("-",""))}${c("16 State wages",t2(x.b1))}${c("17 State income tax",t2(Math.round(x.b1*.035)))}</div>
   ${tap?"":`<div class="vnote">Made-up practice form. Type boxes b, 1, 2, 4 and 6 into the W-2 screen exactly as printed. Boxes 15 to 17 belong to the state return.</div>`}</div>`}
function tw2Pick(c,r){const W=c.docs.filter(d=>d.k==="w2");if(!W.length)return "";let i=tv.w2i;if(i==null||!W[i])i=Math.max(0,W.findIndex(x=>!r.w2.some(y=>y.ein===x.ein)));
  return (W.length>1?`<div class="filters">${W.map((x,k)=>`<button aria-pressed="${k===i}" data-tw2i="${k}">${esc(x.emp)}</button>`).join("")}</div>`:"")+w2Html(W[i],true)}
function tw2Check(c,x){if(tv.solo)return "W-2 saved.";const k=c.key.w2.find(y=>y.ein===(x.ein||"").trim())||c.key.w2.find(y=>y.b1===+x.b1);
  if(!k)return "Saved, but no W-2 in this client's documents has that EIN or those wages. Compare with the Documents tab; remove it and enter it again if it is wrong.";
  const bad=[["ein","Box b (EIN)"],["b1","Box 1"],["b2","Box 2"],["b4","Box 4"],["b6","Box 6"]].filter(f=>String(x[f[0]]).trim()!==String(k[f[0]]));
  return bad.length?"Saved, but it does not match the paper W-2: "+bad.map(f=>f[1]+" shows "+k[f[0]]+", you entered "+(x[f[0]]||"nothing")).join("; ")+". Remove it and enter it again.":"✓ W-2 saved and every box matches the document. Wages went to Form 1040 line 1a and box 2 to line 25a."}
function tcCheck(c,r){const k=c.key.c||{},x=r.c||{};if(tv.solo)return "Schedule C saved.";if(!k.gross)return (+x.gross||+x.adv||+x.off||+x.rent||+x.oth)?"Saved, but this client has no business. Clear the Schedule C screen.":"Saved.";
  const bad=[["gross","gross receipts"],["adv","advertising"],["off","office expense"],["rent","rent"],["oth","other expenses"]].filter(f=>(+x[f[0]]||0)!==(k[f[0]]||0)).map(f=>f[1]);
  return bad.length?"Saved, but check "+bad.join(", ")+" against the bank summary. Remember: a loan is not income and a draw is not an expense.":"✓ Schedule C matches the records. Net profit flows to Form 1040 and to Schedule SE."}
